@Component
class RequestBodyLoggingFilter extends OncePerRequestFilter {
    private static final Logger log = LoggerFactory.getLogger(RequestBodyLoggingFilter.class);
    private static final int MAX_LOGGED = 2_000;

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        var wrapped = new ContentCachingRequestWrapper(request, MAX_LOGGED);
        try {
            chain.doFilter(wrapped, response);              // Jackson đọc qua wrapper, wrapper giữ bản sao
        } finally {
            byte[] body = wrapped.getContentAsByteArray();   // chỉ có sau khi đã được đọc
            log.info("{} {} status={} body={}", request.getMethod(), request.getRequestURI(),
                     response.getStatus(), mask(new String(body, StandardCharsets.UTF_8)));
        }
    }

    private String mask(String body) { /* che password, số thẻ... tự viết theo API */ return body; }
}
